// test/cbor.test.js
//
// Every hex vector below is transcribed directly from RFC 8949
// Appendix A ("Examples") -- independently published, spec-authoritative
// encodings, not generated by this codebase's own encoder (this
// codebase has no CBOR *encoder* at all, only the decoder under test).
// This is deliberate: round-tripping through your own code never
// catches a decoder bug that matches an equally wrong encoder.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { decodeCbor, decodeCborAt } from '../worker/cbor.js';

function hexToBytes(hex) {
  const clean = hex.replace(/\s+/g, '');
  const bytes = new Uint8Array(clean.length / 2);
  for (let i = 0; i < bytes.length; i++) bytes[i] = parseInt(clean.substr(i * 2, 2), 16);
  return bytes;
}

test('unsigned integers (RFC 8949 Appendix A)', () => {
  assert.equal(decodeCbor(hexToBytes('00')), 0);
  assert.equal(decodeCbor(hexToBytes('01')), 1);
  assert.equal(decodeCbor(hexToBytes('0a')), 10);
  assert.equal(decodeCbor(hexToBytes('17')), 23);
  assert.equal(decodeCbor(hexToBytes('1818')), 24);
  assert.equal(decodeCbor(hexToBytes('1819')), 25);
  assert.equal(decodeCbor(hexToBytes('1864')), 100);
  assert.equal(decodeCbor(hexToBytes('1903e8')), 1000);
  assert.equal(decodeCbor(hexToBytes('1a000f4240')), 1000000);
});

test('negative integers (RFC 8949 Appendix A)', () => {
  assert.equal(decodeCbor(hexToBytes('20')), -1);
  assert.equal(decodeCbor(hexToBytes('29')), -10);
  assert.equal(decodeCbor(hexToBytes('3863')), -100);
  assert.equal(decodeCbor(hexToBytes('3903e7')), -1000);
});

test('text strings (RFC 8949 Appendix A)', () => {
  assert.equal(decodeCbor(hexToBytes('60')), '');
  assert.equal(decodeCbor(hexToBytes('6161')), 'a');
  assert.equal(decodeCbor(hexToBytes('6449455446')), 'IETF');
});

test('byte strings (RFC 8949 Appendix A)', () => {
  const result = decodeCbor(hexToBytes('4401020304'));
  assert.deepEqual([...result], [1, 2, 3, 4]);
});

test('arrays (RFC 8949 Appendix A)', () => {
  assert.deepEqual(decodeCbor(hexToBytes('80')), []);
  assert.deepEqual(decodeCbor(hexToBytes('83010203')), [1, 2, 3]);
});

test('maps (RFC 8949 Appendix A)', () => {
  const empty = decodeCbor(hexToBytes('a0'));
  assert.equal(empty.size, 0);

  const intMap = decodeCbor(hexToBytes('a201020304'));
  assert.equal(intMap.get(1), 2);
  assert.equal(intMap.get(3), 4);

  const mixedMap = decodeCbor(hexToBytes('a26161016162820203'));
  assert.equal(mixedMap.get('a'), 1);
  assert.deepEqual(mixedMap.get('b'), [2, 3]);
});

test('negative CBOR map keys decode correctly (used for COSE key labels like -1, -2, -3)', () => {
  const map = decodeCbor(hexToBytes('a12021'));
  assert.equal(map.get(-1), -2);
});

test('decodeCborAt decodes one item mid-buffer and reports how many bytes it consumed', () => {
  const bytes = hexToBytes('aabbcc' + '0a' + '6449455446');
  const first = decodeCborAt(bytes, 3);
  assert.equal(first.value, 10);
  assert.equal(first.offset, 4);

  const second = decodeCborAt(bytes, first.offset);
  assert.equal(second.value, 'IETF');
  assert.equal(second.offset, bytes.length);
});

test('throws on truncated input rather than reading out of bounds', () => {
  assert.throws(() => decodeCbor(hexToBytes('440102')));
});

test('throws on unsupported indefinite-length items rather than silently misparsing', () => {
  assert.throws(() => decodeCbor(hexToBytes('5f')));
});
